fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0, we can safely iterate starting from the second element.
    for i in 1..arr.len() {
        // If any pair of adjacent elements violates the nondecreasing order,
        // the entire array is not sorted.
        if arr[i] < arr[i - 1] {
            return false;
        }
    }
    // If no violations found, the array is sorted in nondecreasing order.
    true
}